CREATE TABLE credentials(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,username VARCHAR(150) NOT NULL,encrypted_password TEXT NOT NULL,encryption_iv VARCHAR(255) NOT NULL,auth_type VARCHAR(30) NOT NULL DEFAULT 'PASSWORD',created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());ALTER TABLE machines ADD COLUMN preferred_credential_id BIGINT REFERENCES credentials(id);ALTER TABLE machines ADD COLUMN ssh_host_key TEXT;ALTER TABLE machines ADD COLUMN ssh_fingerprint TEXT;ALTER TABLE machines ADD COLUMN fingerprint_verified_at TIMESTAMPTZ;